def transform(grid):
    g=[row[:] for row in grid]
    pts={}
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v!=1: pts.setdefault(v,[]).append((r,c))
    for color, ps in pts.items():
        for r,c in ps:
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                if (r+dr,c+dc) in ps:
                    rr,cc=r+2*dr,c+2*dc
                    while 0<=rr<len(g) and 0<=cc<len(g[0]) and g[rr][cc]==1:
                        g[rr][cc]=color; rr+=dr; cc+=dc
                    return g
    return g
